mapper.select:
SELECT AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, SDV.VALUE_NAME AS PAYMENT_SIGN_NAME, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, DATE_FORMAT(AC.PAYMENT_TIME, '%Y-%m-%d') AS PAYMENT_TIME_GROUPING_KEY FROM account_cost AC LEFT JOIN SYS_DICT_VALUE SDV ON SDV.DICT_KEY = 'PAYMENT_SIGN' WHERE 1=1 AND AC.LOGIC_DEL = 0
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
GROUP BY AC.PAYMENT_TIME, AC.CREATE_TIME ORDER BY AC.PAYMENT_TIME DESC, AC.CREATE_TIME ASC

SELECT
T.COST_TYPE,
SUM(T.OUTLAY) AS OUTLAY
FROM
(
(

WHERE 1=1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.USER_ID = #{accountCostDto.userId}

    AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
    AND AC.PAYMENT_TIME <=  #{accountCostDto.paymentTimeTo}

)

UNION

(

WHERE 1=1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND ACU.USER_ID = #{accountCostDto.userId}
AND AC.USER_ID <> #{accountCostDto.userId}

    AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
    AND AC.PAYMENT_TIME <=  #{accountCostDto.paymentTimeTo}

)
) T
GROUP BY T.COST_TYPE

SELECT
SUM(T.OUTLAY) AS OUTLAY,
T.PAYMENT_TIME,
T.X_AXIS
FROM (
(

WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.USER_ID = #{accountCostDto.userId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
)

UNION

(

WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND ACU.USER_ID = #{accountCostDto.userId}
AND AC.USER_ID <> #{accountCostDto.userId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
)
) T
GROUP BY DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d')

SELECT
SUM(T.OUTLAY) AS OUTLAY,
T.PAYMENT_TIME,
T.X_AXIS
FROM
(
(

WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.USER_ID = #{accountCostDto.userId}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year}
AND MONTH(AC.PAYMENT_TIME) = #{accountCostDto.month}
)

UNION

(

WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND ACU.USER_ID = #{accountCostDto.userId}
AND AC.USER_ID <> #{accountCostDto.userId}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year}
AND MONTH(AC.PAYMENT_TIME) = #{accountCostDto.month}
)
) T
GROUP BY DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d')

SELECT
SUM(T.OUTLAY) AS OUTLAY,
T.PAYMENT_TIME,
T.X_AXIS
FROM
(
(

WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.USER_ID = #{accountCostDto.userId}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year}
)

UNION

(

WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.PAYMENT_SIGN = 'EXPENSES'
AND ACU.USER_ID = #{accountCostDto.userId}
AND AC.USER_ID <> #{accountCostDto.userId}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year}
)

) T
GROUP BY DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m')

SELECT
SUM(T.OUTLAY) AS OUTLAY,
T.PAYMENT_TIME,
T.X_AXIS
FROM (
(

WHERE 1 = 1
AND AC.USER_ID = #{accountCostDto.userId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
)

UNION

(

WHERE 1 = 1
AND AC.USER_ID <> #{accountCostDto.userId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
)
) T
GROUP BY DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d')

( SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID LEFT JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID = #{accountCost.userId}
AND AC.COST_DESC = #{accountCost.costDesc}
AND AC.REMARK = #{accountCost.remark}
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_TIME >= #{accountCost.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCost.paymentTimeTo}
GROUP BY AC.ID )
UNION
( SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID INNER JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID <> #{accountCost.userId}
AND AC.COST_DESC = #{accountCost.costDesc}
AND AC.REMARK = #{accountCost.remark}
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_TIME >= #{accountCost.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCost.paymentTimeTo}
GROUP BY AC.ID ) ORDER BY PAYMENT_TIME DESC, MODIFY_TIME DESC

( SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID LEFT JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID = #{accountCost.userId}
AND AC.ID = #{accountCost.id}
GROUP BY AC.ID )
UNION
( SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID INNER JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID <> #{accountCost.userId}
AND ACU.COST_ID = #{accountCost.id}
GROUP BY AC.ID )
